-- SMASHBANDITS(AU.01)[X64]-V14
-- Do not edit this file. Any change breaks the decoder.
local _ueoims = 66
local _kiimez = 150
local _eicqrk = 55
local _lfchpp = ""

local _anmvwr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _qrfgoi(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _xonqqr(d)
	d = d:gsub("[^" .. _anmvwr .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_anmvwr:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _kuafmf = _xonqqr(_lfchpp)
local _hnfdvv = { _ueoims, _kiimez, _eicqrk }
local _obkmhg = {}
for i = 1, #_kuafmf do
	_obkmhg[i] = string.char(_qrfgoi(_kuafmf:byte(i), _hnfdvv[(i - 1) % 3 + 1]))
end

local _gpwarz = load or loadstring
local _mjbtfv, _wfymbp = _gpwarz(table.concat(_obkmhg), "=w")
if not _mjbtfv then
	gg.alert("Corrupted file: " .. tostring(_wfymbp))
	os.exit()
end
_mjbtfv()
